import { describe, it, expect } from 'vitest';
import { render, screen } from '@testing-library/react';
import UserStats from './UserStats';
import React from 'react';

describe('UserStats', () => {
  it('displays correct stats for mixed users', () => {
    const users = [
      { id: 1, name: 'Active1', isActive: true },
      { id: 2, name: 'Inactive1', isActive: false },
      { id: 3, name: 'Active2', isActive: true },
      { id: 4, name: 'Inactive2', isActive: false },
    ];
    render(<UserStats users={users} />);

    expect(screen.getByText(/Active Users: 2/i)).toBeDefined();
    expect(screen.getByText(/Inactive Users: 2/i)).toBeDefined();
    expect(screen.getByText(/Active Percentage: 50.0%/i)).toBeDefined();
  });

  it('handles empty user list', () => {
    render(<UserStats users={[]} />);

    expect(screen.getByText(/Active Users: 0/i)).toBeDefined();
    expect(screen.getByText(/Inactive Users: 0/i)).toBeDefined();
    expect(screen.getByText(/Active Percentage: 0.0%/i)).toBeDefined();
  });

  it('handles all active users', () => {
    const users = [
      { id: 1, name: 'Active1', isActive: true },
      { id: 2, name: 'Active2', isActive: true },
    ];
    render(<UserStats users={users} />);

    expect(screen.getByText(/Active Users: 2/i)).toBeDefined();
    expect(screen.getByText(/Inactive Users: 0/i)).toBeDefined();
    expect(screen.getByText(/Active Percentage: 100.0%/i)).toBeDefined();
  });

  it('handles all inactive users', () => {
    const users = [
      { id: 1, name: 'Inactive1', isActive: false },
      { id: 2, name: 'Inactive2', isActive: false },
    ];
    render(<UserStats users={users} />);

    expect(screen.getByText(/Active Users: 0/i)).toBeDefined();
    expect(screen.getByText(/Inactive Users: 2/i)).toBeDefined();
    expect(screen.getByText(/Active Percentage: 0.0%/i)).toBeDefined();
  });
});

